whatis("Name: r-bioconductor")
whatis("Version: 3.23-R-4.6.1")
whatis("Description: R 4.6.1 / Bioconductor 3.23 container with RStudio Desktop, TeX and Quarto.")
whatis("Home page: https://www.bioconductor.org/")

if not (os.getenv("BIOC_SINGULARITY_MODULE") == "none") then
   local singularity_module = os.getenv("BIOC_SINGULARITY_MODULE") or "Singularity"
   if not (isloaded(singularity_module)) then
      load(singularity_module)
   end
end

conflict(myModuleName(), "R", "R-bioconductor", "Rstudio", "r", "rstudio", "r-rstudio", "r-rnaseq")

local image = sif
if os.getenv("BIOC_IMAGE_DIR") then
   image = pathJoin(os.getenv("BIOC_IMAGE_DIR"), sif:match("[^/]+$"))
end
-- Fail at load time rather than pulling a ~10 GB image into the user's cache on first use.
if (mode() == "load" and not isFile(image)) then
   LmodError("r-bioconductor/3.23-R-4.6.1: image not found: " .. image)
end

-- The absolute path to Singularity is needed so it can be invoked on remote
-- nodes without the corresponding module necessarily being loaded.
local singularity = capture("which singularity 2>/dev/null | head -c -1")
if (singularity == "") then singularity = "/usr/bin/singularity" end

local run_args = {}

-- GPU flags. Probed only on load, so `module avail/spider/show` stay fast.
if (mode() == "load") then
   if (capture("nvidia-smi -L 2>/dev/null") ~= "") then
      LmodMessage("BIOC: Enabling Nvidia GPU support in the container.")
      table.insert(run_args, "--nv")
   end
   if (capture("/opt/rocm/bin/rocm-smi -i 2>/dev/null | grep ^GPU") ~= "") then
      LmodMessage("BIOC: Enabling AMD GPU support in the container.")
      table.insert(run_args, "--rocm")
   end
end

-- Need these for X11 under ThinLinc.
table.insert(run_args, "-B /var/opt,/run/user")

-- Per-release extras library, mounted where Renviron.site expects it. One directory per
-- image tag keeps packages ABI-matched to this image. Skipped if absent: apptainer refuses
-- to start when a bind source is missing.
if isDir(extras) then
   table.insert(run_args, "-B " .. extras .. ":/opt/R/host-site-library:ro")
end

local container = singularity .. " exec " .. table.concat(run_args, " ") .. " "

for _, program in ipairs({"R", "Rscript", "quarto"}) do
   set_shell_function(program, container .. image .. " " .. program .. " \"$@\"",
                               container .. image .. " " .. program .. " $*")
end

-- RStudio needs the host X11 fonts, otherwise terminal and editor tabs get badly garbled.
-- Bound for rstudio only: it hides the image's own fonts, which R graphics and TeX use.
local desktop = container .. "-B /usr/share/fonts " .. image .. " rstudio --no-sandbox"
set_shell_function("rstudio", desktop .. " \"$@\"", desktop .. " $*")

-- Use the image's C and Fortran compilers for source packages: keep compiler variables
-- from host modules out of the container (otherwise source packages don't build).
pushenv("APPTAINERENV_CC",  "")
pushenv("APPTAINERENV_CXX", "")
pushenv("APPTAINERENV_FC",  "")
pushenv("APPTAINERENV_F77", "")
pushenv("APPTAINERENV_F90", "")
pushenv("APPTAINERENV_F95", "")
-- An R_LIBS exported in a user's shell outranks every library path set in Renviron.site.
pushenv("APPTAINERENV_R_LIBS", "")

-- Ensure default values for thread numbers, otherwise performance suffers
-- (when cgroup-ed Slurm job tries to spawn `nproc` threads on a single core)
if (mode() == "load") then
   if os.getenv("OMP_NUM_THREADS") == nil then
      setenv("OMP_NUM_THREADS", 1)
   end
   if os.getenv("OPENBLAS_NUM_THREADS") == nil then
      setenv("OPENBLAS_NUM_THREADS", 1)
   end
end
